function serializeOptions(options) {
  if (
    options === null ||
    typeof options !== "object" ||
    Array.isArray(options) ||
    !(
      Object.getPrototypeOf(options) === Object.prototype ||
      Object.getPrototypeOf(options) === null
    )
  ) {
    throw new TypeError("Invalid options");
  }

  const pairs = [];

  for (const name of Object.keys(options)) {
    const value = options[name];

    if (value === undefined) continue;

    let stringValue;
    if (value === null) {
      stringValue = "";
    } else if (typeof value === "string") {
      stringValue = value;
    } else if (typeof value === "number") {
      if (!Number.isFinite(value)) throw new TypeError("Invalid value");
      stringValue = String(value);
    } else if (typeof value === "boolean") {
      stringValue = String(value);
    } else {
      throw new TypeError("Invalid value");
    }

    const encodedName = encodeRFC3986(name);
    const encodedValue = encodeRFC3986(stringValue);
    pairs.push([encodedName, encodedValue]);
  }

  pairs.sort((a, b) => {
    const nameOrder = a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0;
    return nameOrder || (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0);
  });

  return pairs.map(([name, value]) => name + "=" + value).join("&");
}

function encodeRFC3986(string) {
  let result = "";

  for (let i = 0; i < string.length; i++) {
    const code = string.charCodeAt(i);

    if (code >= 0xd800 && code <= 0xdbff) {
      if (i + 1 >= string.length) throw new URIError("Unpaired surrogate");
      const next = string.charCodeAt(++i);
      if (next < 0xdc00 || next > 0xdfff) {
        throw new URIError("Unpaired surrogate");
      }

      const codePoint =
        0x10000 + ((code - 0xd800) << 10) + (next - 0xdc00);

      result += utf8(codePoint);
    } else if (code >= 0xdc00 && code <= 0xdfff) {
      throw new URIError("Unpaired surrogate");
    } else if (
      (code >= 0x41 && code <= 0x5a) ||
      (code >= 0x61 && code <= 0x7a) ||
      (code >= 0x30 && code <= 0x39) ||
      code === 0x2d ||
      code === 0x2e ||
      code === 0x5f ||
      code === 0x7e
    ) {
      result += String.fromCharCode(code);
    } else {
      result += utf8(code);
    }
  }

  return result;
}

function utf8(codePoint) {
  const bytes = [];

  if (codePoint <= 0x7f) {
    bytes.push(codePoint);
  } else if (codePoint <= 0x7ff) {
    bytes.push(
      0xc0 | (codePoint >> 6),
      0x80 | (codePoint & 0x3f)
    );
  } else if (codePoint <= 0xffff) {
    bytes.push(
      0xe0 | (codePoint >> 12),
      0x80 | ((codePoint >> 6) & 0x3f),
      0x80 | (codePoint & 0x3f)
    );
  } else {
    bytes.push(
      0xf0 | (codePoint >> 18),
      0x80 | ((codePoint >> 12) & 0x3f),
      0x80 | ((codePoint >> 6) & 0x3f),
      0x80 | (codePoint & 0x3f)
    );
  }

  return bytes
    .map(byte => "%" + byte.toString(16).toUpperCase().padStart(2, "0"))
    .join("");
}
